    {
      "keystrokes": "tesseract /app/frames/sample_009.png stdout --psm 6 tsv 2>/dev/null | tail -30\n",
      "duration": 1.0
    }
  ]
}

{
  "analysis": "The previous batch produced a lot of output but the screen is showing only the tail. The Tesseract TSV command appears to have just run or is still running. I need get the TSV bounding box output to determine the prompt line crop region. Let's run a focused TSV command and filter for lines containing prompt characters or the last text entries.",
  "plan": "Run Tesseract TSV on a sample frame and filter for words with their bounding boxes, especially lines with '>' or commands. This will identify coordinates for cropping the input prompt area from frames.",
  "commands": [
    {
      "keystrokes": "tesseract /app/frames/sample_009.png stdout --psm 6 tsv 2>/dev/null | awk -F'\\t' 'NF>10 {print $12, $7, $8, $9, $10, $11}' | tail -60\n",
      "duration": 1.0
