    {
      "keystrokes": "tesseract /app/frames/sample_001.png stdout --psm 6 tsv 2>/dev/null | awk -F'\\t' 'NF>10 {print $12, $7, $8, $9, $10, $11}' | tail -40\n",
      "duration": 1.0
